<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import * as echarts from 'echarts';
import {ElMessage} from 'element-plus';
import UiIcon from './UiIcon.vue';
import ShoppingLinks from './ShoppingLinks.vue';
import ProductImage from './ProductImage.vue';
import {restoredPairIds} from './advisorContext';
import {api,categories,labels,priceText} from './api';
const props=defineProps({context:Object});const emit=defineEmits(['navigate']);
const category=ref(props.context.profile.category),budget=ref(props.context.profile.budget),pool=ref([]),busy=ref(false),aId=ref(null),bId=ref(null),barEl=ref(null),radarEl=ref(null);
const a=computed(()=>pool.value.find(p=>p.id===aId.value)),b=computed(()=>pool.value.find(p=>p.id===bId.value));
const metricKeys=computed(()=>Object.keys(labels).filter(k=>a.value?.metrics[k]!=null||b.value?.metrics[k]!=null));
const common=computed(()=>metricKeys.value.filter(k=>a.value?.metrics[k]!=null&&b.value?.metrics[k]!=null));
const factLabels={weight:'重量 / 标注范围',memory:'内存 / 标注范围',cpu_cores:'CPU 核心数',battery_mah:'电池标称容量',battery_hours:'续航 / 标注范围',refresh:'屏幕刷新率',camera_mp:'影像像素规格',burst:'标注连拍速度',screen_inches:'屏幕尺寸'};
const facts=computed(()=>Object.keys(factLabels).filter(k=>a.value?.facts[k]||b.value?.facts[k]));
const comparison=ref(null),hideSame=ref(false),highlight=ref(true),pairBusy=ref(false),pairError=ref('');let pairSeq=0;
const groups=computed(()=>(comparison.value?.groups||[]).map(g=>({...g,rows:g.rows.filter(r=>!hideSame.value||r.state!=='same')})).filter(g=>g.rows.length));
async function loadParameters(){const token=++pairSeq;comparison.value=null;pairError.value='';if(!a.value||!b.value)return;pairBusy.value=true;try{const result=await api('compare',{...props.context.profile,category:category.value,budget:budget.value,subcategory:null,needs:'',product_ids:[aId.value,bId.value]});if(token!==pairSeq||disposed)return;comparison.value=result;props.context.comparePair=[a.value,b.value];props.context.selectedId=aId.value;if(props.context.profile.category!==category.value)props.context.profile.needs='预算'+budget.value+'元，选购'+category.value+'。';props.context.profile.category=category.value;props.context.profile.budget=budget.value;props.context.products=[a.value,b.value,...props.context.products.filter(p=>p.id!==aId.value&&p.id!==bId.value)];}catch(e){if(token===pairSeq)pairError.value=e.message}finally{if(token===pairSeq)pairBusy.value=false}}
let seq=0,timer,charts=[],disposed=false,restorePair=true;
async function load(){const current=++seq;busy.value=true;try{const data=await api('recommend',{...props.context.profile,category:category.value,budget:budget.value,subcategory:null,needs:'',purpose:'compare'});if(current!==seq||disposed)return;pool.value=data.products;if(pool.value.length<2&&props.context.profile.curated_only){props.context.profile.curated_only=false;await load();return;}const seed=props.context.compareSeedId;const remembered=restorePair?restoredPairIds(pool.value,seed,props.context.comparePair):null;if(remembered){aId.value=remembered[0];bId.value=remembered[1]}restorePair=false;if(seed&&pool.value.some(p=>p.id===seed)){aId.value=seed;props.context.compareSeedId=null;}if(!pool.value.some(p=>p.id===aId.value))aId.value=pool.value[0]?.id;if(!pool.value.some(p=>p.id===bId.value)||aId.value===bId.value)bId.value=pool.value.find(p=>p.id!==aId.value)?.id;await nextTick();draw()}catch(e){if(!disposed)ElMessage.error(e.message)}finally{if(current===seq)busy.value=false}}
function randomPair(){if(pool.value.length<2)return;const first=Math.floor(Math.random()*pool.value.length);let second=Math.floor(Math.random()*(pool.value.length-1));if(second>=first)second++;aId.value=pool.value[first].id;bId.value=pool.value[second].id;}
function swap(){[aId.value,bId.value]=[bId.value,aId.value]}
function choose(p){if(p.id===aId.value||p.id===bId.value)return;bId.value=p.id;}
function dispose(){charts.forEach(c=>c.dispose());charts=[]}
function draw(){dispose();if(!a.value||!b.value)return;const colors=['#7662e8','#16a991'];if(barEl.value){const chart=echarts.init(barEl.value);chart.setOption({color:colors,tooltip:{trigger:'axis',axisPointer:{type:'shadow'}},legend:{bottom:0,textStyle:{fontSize:11}},grid:{top:16,bottom:65,left:85,right:25},xAxis:{type:'value',max:100,splitLine:{lineStyle:{color:'#eff0f6'}}},yAxis:{type:'category',inverse:true,data:metricKeys.value.map(k=>labels[k]),axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:11,color:'#777c91'}},series:[a.value,b.value].map(p=>({name:p.name,type:'bar',barMaxWidth:13,itemStyle:{borderRadius:[0,4,4,0]},data:metricKeys.value.map(k=>p.metrics[k])}))});charts.push(chart)}if(radarEl.value&&common.value.length>=3){const chart=echarts.init(radarEl.value);chart.setOption({color:colors,tooltip:{},legend:{bottom:0,textStyle:{fontSize:11}},radar:{radius:'62%',center:['50%','46%'],indicator:common.value.map(k=>({name:labels[k],max:100})),axisName:{fontSize:11,color:'#777c91'},splitArea:{areaStyle:{color:['#fff','#fafaff']}},splitLine:{lineStyle:{color:'#e9eaf4'}}},series:[{type:'radar',data:[a.value,b.value].map(p=>({name:p.name,value:common.value.map(k=>p.metrics[k]),areaStyle:{opacity:.10},lineStyle:{width:2}}))}]});charts.push(chart)}}
watch([aId,bId],async()=>{await nextTick();draw();loadParameters()});watch([category,budget],()=>{clearTimeout(timer);timer=setTimeout(async()=>{await load();loadParameters()},250)});
function resize(){charts.forEach(c=>c.resize())}onMounted(()=>{load();window.addEventListener('resize',resize)});onBeforeUnmount(()=>{disposed=true;seq++;clearTimeout(timer);dispose();window.removeEventListener('resize',resize)});
</script>
<template>
<section class="comparison-page"><div class="page-heading"><div><span class="eyebrow">SIDE BY SIDE</span><h1>差别，看得见</h1><p>自由挑选两款产品，从参数、预算与使用重点一起比较。</p></div><button class="secondary-btn" :disabled="pool.length<2||busy" @click="randomPair"><UiIcon name="shuffle" :size="17"/> 随机选两款</button></div>
 <div class="compare-filter panel"><label>产品类别<el-select v-model="category"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></label><label>参考预算<el-input-number v-model="budget" :min="1" :max="50000" :step="100"/></label><label class="small"><input type="checkbox" v-model="context.profile.curated_only" @change="load"/>精选档案</label><span class="muted small">可切换精选或全部产品；参考排名包含待核价和超预算项，不等于预算内推荐。</span></div>
 <div class="comparison-layout" v-loading="busy"><aside class="ranking-panel panel"><div class="panel-caption"><h3>产品参考排名</h3><span>{{pool.length}} 款</span></div><p class="muted small">点击一款可替换右侧 B 产品</p><div class="ranking-list"><button v-for="(p,i) in pool" :key="p.id" :class="['rank-row',(p.id===aId||p.id===bId)&&'chosen']" @click="choose(p)"><span class="rank-number">{{String(i+1).padStart(2,'0')}}</span><span>{{p.name}}<small>{{p.subcategory}} <b v-if="p.id===aId">A</b><b v-if="p.id===bId">B</b></small></span><strong>{{p.score.toFixed(2)}}</strong></button></div></aside>
 <div class="comparison-main"><div class="pair-selectors"><label><span class="pair-letter">A</span><el-select v-model="aId" filterable placeholder="选择产品 A" aria-label="选择产品 A"><el-option v-for="p in pool" :key="p.id" :label="p.name" :value="p.id" :disabled="p.id===bId"/></el-select></label><button class="swap-button" @click="swap" aria-label="交换产品"><UiIcon name="refresh" :size="17"/></button><label><span class="pair-letter mint">B</span><el-select v-model="bId" filterable placeholder="选择产品 B" aria-label="选择产品 B"><el-option v-for="p in pool" :key="p.id" :label="p.name" :value="p.id" :disabled="p.id===aId"/></el-select></label></div>
 <template v-if="a&&b"><div class="pair-cards"><article v-for="(p,index) in [a,b]" :key="p.id" :class="['pair-card',index===1&&'mint-card']"><ProductImage :product="p"/><span class="product-meta">{{p.brand}} · {{p.subcategory}}</span><h2>{{p.name}}</h2><div class="pair-score"><strong>{{p.score.toFixed(2)}}</strong><span>选购参考分<br><small>评分信息覆盖 {{p.confidence}}%</small></span></div><b class="pair-price">{{priceText(p)}}</b><p class="muted small">{{p.budget_status}}</p><button class="text-btn" @click="emit('navigate','report',p)">为这款生成报告 ↗</button><ShoppingLinks :product="p" compact/></article></div>
 <div class="compare-chart-grid"><div class="panel"><h3>多维参考分</h3><p class="muted small">未知维度留空，不记作零分</p><div ref="barEl" class="comparison-chart"></div></div><div class="panel"><h3>共同维度雷达</h3><p class="muted small">仅展示双方都能核对的维度</p><div v-if="common.length>=3" ref="radarEl" class="comparison-chart"></div><el-empty v-else description="共同维度不足三项，请查看参数表" :image-size="70"/></div></div>
 <div v-if="comparison" class="decision-panel panel"><div class="panel-caption"><h3>怎样选，更适合你</h3><span class="soft-label">按当前预算与偏好解释</span></div><div class="decision-grid"><article v-for="(d,i) in comparison.decisions" :key="d.product_id"><b>{{i===0?'A':'B'}} · {{[a,b][i].name}}</b><p>{{d.text}}</p><ul><li v-for="item in d.advantages.slice(0,2)" :key="item.metric">{{item.label}}：{{item.basis}}</li></ul></article></div><p class="muted small">{{comparison.cautions.join(' ')}}</p></div>
 <div class="comparison-facts" v-loading="pairBusy"><p v-if="pairError" role="alert">{{pairError}} <button class="text-btn" @click="loadParameters">重试</button></p><template v-if="comparison"><div class="spec-toolbar panel"><div><h3>把参数放在一起看</h3><p>{{comparison.counts.total}} 项原文 · {{comparison.counts.different}} 项差异 · {{comparison.counts.same}} 项相同 · {{comparison.counts.unknown}} 项待补</p></div><label><input v-model="hideSame" type="checkbox"/> 隐藏相同项</label><label><input v-model="highlight" type="checkbox"/> 差异高亮</label></div><div class="spec-layout"><nav class="spec-navigation" aria-label="参数分组"><a v-for="g in groups" :key="g.id" :href="'#'+g.id">{{g.name}}<span>{{g.rows.length}}</span></a></nav><div class="spec-table-wrap"><div class="sticky-products"><div class="spec-column-label">官方参数对照<small>原文不同 ≠ 实测胜出</small></div><article v-for="(p,i) in [a,b]" :key="p.id"><ProductImage :product="p"/><div><small>{{i===0?'A':'B'}} · {{p.brand}}</small><strong>{{p.name}}</strong><b>{{priceText(p)}}</b></div></article></div><section v-for="g in groups" :key="g.id" :id="g.id" class="spec-section"><h3>{{g.name}}</h3><div v-for="(r,idx) in g.rows" :key="idx" :class="['spec-row',highlight&&r.state==='different'&&'different',r.state==='unknown'&&'unknown']"><div class="spec-label">{{r.label}}<small v-if="r.state==='different'">原文有差异</small></div><div v-for="(v,i) in r.values" :key="i" class="spec-value"><template v-if="v"><p>{{v.value}}</p><a :href="v.source_url" target="_blank" rel="noopener noreferrer">{{v.section}} · 原文 ↗</a></template><span v-else>暂无可核对数据<small>未披露不等于不支持</small></span></div></div></section><div v-if="!groups.length" class="panel muted">当前显示项全部相同，可关闭“隐藏相同项”查看。</div></div></div></template></div><p class="page-footnote">参考分表示当前规则下的选购倾向；系列、地区和测试条件不同的参数需结合原文确认，不能代替实测体验。</p></template><el-empty v-else-if="!busy" description="当前类别不足两款，请选择其他类别"/></div></div>
</section>
</template>
